//! 🔎️ Declared schema leaves and flattened branches are matched against one genuinely bound original key.
use super::NativeRecordKey;
use crate::{NativeDecodeControl,OriginalReceivingPrimary,RetainedWorkOutcome,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneBinding,RetainedCloneRef,retained_clone_grant_admits},owned::tree::{NativeValueSource,fixed,receipt,invalid}};
use semio_framework_value_persistent::list::{PagedList,PagedListError};
use std::mem::{ManuallyDrop,size_of};
/// 🧩️ A pure borrowed descriptor selects one leaf or one nested schema table.
#[derive(Clone,Copy)]pub struct NativeSchemaLeaf{pub name:&'static str,pub ordinal:u32}
#[derive(Clone,Copy)]pub enum NativeRecordSchema{Leaf(NativeSchemaLeaf),Flatten{fields:fn(usize)->Option<NativeRecordSchema>,count:usize},Union{fields:fn(usize)->Option<NativeRecordSchema>,count:usize},Skip}
/// 🔑️ One declared original accessor selects the genuinely borrowed key without speculative error probes.
#[derive(Clone,Copy)]pub enum NativeSchemaKeySource{Record(usize),Text,VariantTag,EnumOrdinal,RecordName(usize),RecordText(usize)}
/// 🪪️ Ambiguity preserves the same duplicate-schema refusal without scanning unnecessary later leaves.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum NativeFieldMatch{Missing,Field(usize),Ambiguous}
#[derive(Clone,Copy)]struct SchemaFrame{fields:fn(usize)->Option<NativeRecordSchema>,count:usize,index:usize,root:Option<usize>,role:u8,before:NativeFieldMatch,best:NativeFieldMatch}
#[derive(Clone,Copy)]enum Key{Name(*const str),Ordinal(u32)}
fn combined(left:NativeFieldMatch,right:NativeFieldMatch)->NativeFieldMatch{match(left,right){(NativeFieldMatch::Missing,right)=>right,(left,NativeFieldMatch::Missing)=>left,_=>NativeFieldMatch::Ambiguous}}
fn alternative(left:NativeFieldMatch,right:NativeFieldMatch)->NativeFieldMatch{match(left,right){(NativeFieldMatch::Ambiguous,_)|(_,NativeFieldMatch::Ambiguous)=>NativeFieldMatch::Ambiguous,(NativeFieldMatch::Missing,right)=>right,(left,_)=>left}}
fn page<T>(r:Result<T,PagedListError>)->Result<T,ValueError>{r.map_err(|e|ValueError::literal(ValueRefusalKind::OwnershipLimit,e.reason))}
/// 🎟️ Stack pages, original binding and current comparison remain resident across all denied or cancelled turns.
pub struct NativeRecordMatcher<I:NativeValueSource+?Sized>{binding:Option<RetainedCloneBinding>,frames:ManuallyDrop<PagedList<SchemaFrame,{usize::MAX}>>,pending:Option<SchemaFrame>,key:Option<Key>,leaf:Option<NativeSchemaLeaf>,leaf_root:usize,offset:usize,key_source:NativeSchemaKeySource,fields:fn(usize)->Option<NativeRecordSchema>,count:usize,matched:NativeFieldMatch,done:bool,closing:bool,input:std::marker::PhantomData<fn(&I)>}
/// 🧵️ The only raw key pointer borrows a Sync original kept alive by the same genuine binding; all stack mutations remain exclusively owned.
unsafe impl<I:NativeValueSource+?Sized>Send for NativeRecordMatcher<I>{}
impl<I:NativeValueSource+?Sized>NativeRecordMatcher<I>{
 pub fn new(fields:fn(usize)->Option<NativeRecordSchema>,count:usize,key_source:NativeSchemaKeySource)->Self{Self{binding:None,frames:ManuallyDrop::new(PagedList::new()),pending:None,key:None,leaf:None,leaf_root:0,offset:0,key_source,fields,count,matched:NativeFieldMatch::Missing,done:false,closing:false,input:std::marker::PhantomData}}
 pub fn result(&self)->Option<NativeFieldMatch>{self.done.then_some(self.matched)}
 pub fn demands(&self,input:RetainedCloneRef<'_,I>,_:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}if self.done{return Ok(Default::default())}if !input.check_binding(&self.binding)?{return Ok(fixed(input.binding_copy_bytes()))}if self.pending.is_some(){if self.frames.has_reserved_slot(){return Ok(RetirementDemand{copy_bytes:size_of::<SchemaFrame>(),depth:page(self.frames.next_push_depth_demand())?.max(1),..Default::default()})}return Ok(RetirementDemand{copy_bytes:page(self.frames.next_reserve_copy_byte_demand())?,capacity_bytes:page(self.frames.next_allocation_bytes())?,depth:page(self.frames.next_reserve_depth_demand())?.max(1),..Default::default()})}if self.key.is_none()||self.leaf.is_some()||self.frames.is_empty(){return Ok(fixed(0))}let mut depth=page(self.frames.next_get_depth_demand(self.frames.len()-1))?.max(1);if self.frames.last().unwrap().index>=self.frames.last().unwrap().count{depth=depth.max(page(self.frames.next_pop_depth_demand())?);}Ok(RetirementDemand{depth,..Default::default()})}
 fn advance_one(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome{if self.done{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let mut work=0;let mut own=RetainedCloneProgress::default();let result:Result<RetainedCloneStep,ValueError>=(||{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;crate::owned::receiving_capacity(control,d.capacity_bytes)?;if self.binding.is_none(){let turn=input.bind(&mut self.binding,g);work=turn.work;return turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default()))}
  if self.pending.is_some(){if !self.frames.has_reserved_slot(){let turn=match self.frames.reserve_one(g.maximum_capacity_bytes){Ok(p)=>RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:usize::from(p.progressed),copied_bytes:p.placed_bytes,retained_capacity_bytes:p.allocated_bytes,released_bytes:p.released_allocation_bytes})),work:p.work},Err(e)=>RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,e.reason).with_retained_progress(RetainedCloneProgress{retained_capacity_bytes:e.allocated_bytes,..Default::default()})),work:e.work}};work=turn.work;return turn.result}let f=self.pending.take().unwrap();self.frames.push_reserved(f).unwrap_or_else(|_|unreachable!("schema row remains exclusively reserved"));work=1;return Ok(RetainedCloneStep::Progress(receipt(d)))}
  work=1;own=receipt(fixed(0));if self.key.is_none(){self.key=Some(match self.key_source{NativeSchemaKeySource::Record(rank)=>match input.get().record_key(rank)?{NativeRecordKey::Name(name)=>Key::Name(name as*const str),NativeRecordKey::Ordinal(n)=>Key::Ordinal(u32::from(n))},NativeSchemaKeySource::Text=>Key::Name(input.get().text()?.as_str()as*const str),NativeSchemaKeySource::VariantTag=>Key::Name(input.get().variant_tag().ok_or_else(invalid)?as*const str),NativeSchemaKeySource::EnumOrdinal=>Key::Ordinal(input.get().enum_ordinal()?),NativeSchemaKeySource::RecordName(rank)=>Key::Name(input.get().record_name(rank)?as*const str),NativeSchemaKeySource::RecordText(rank)=>Key::Name(input.get().record_child(rank)?.text()?.as_str()as*const str)});self.pending=Some(SchemaFrame{fields:self.fields,count:self.count,index:0,root:None,role:0,before:NativeFieldMatch::Missing,best:NativeFieldMatch::Missing});}
  else if let Some(leaf)=self.leaf{let matched=match self.key.unwrap(){Key::Ordinal(n)=>Some(leaf.ordinal==n),Key::Name(ptr)=>{let key=unsafe{&*ptr}.as_bytes();let name=leaf.name.as_bytes();if key.len()!=name.len(){Some(false)}else{let end=self.offset.saturating_add(64).min(name.len());let equal=key[self.offset..end]==name[self.offset..end];self.offset=end;if !equal{Some(false)}else if end==name.len(){Some(true)}else{None}}}};if let Some(matched)=matched{self.leaf=None;if matched{self.matched=match self.matched{NativeFieldMatch::Missing=>NativeFieldMatch::Field(self.leaf_root),_=>NativeFieldMatch::Ambiguous};if self.matched==NativeFieldMatch::Ambiguous{self.done=true;}}}}
  else if let Some(frame)=self.frames.last_mut(){if frame.role==2{frame.best=alternative(frame.best,self.matched);self.matched=NativeFieldMatch::Missing;frame.role=1;}else if frame.index>=frame.count{if frame.role==1{self.matched=combined(frame.before,frame.best);if self.matched==NativeFieldMatch::Ambiguous{self.done=true;}}self.frames.pop();}else{let index=frame.index;let root=frame.root.unwrap_or(index);let node=(frame.fields)(index).ok_or_else(invalid)?;frame.index+=1;if frame.role==1{frame.role=2;self.matched=NativeFieldMatch::Missing;}match node{NativeRecordSchema::Leaf(leaf)=>{self.leaf=Some(leaf);self.leaf_root=root;self.offset=0;},NativeRecordSchema::Flatten{fields,count}=>{self.pending=Some(SchemaFrame{fields,count,index:0,root:Some(root),role:0,before:NativeFieldMatch::Missing,best:NativeFieldMatch::Missing});},NativeRecordSchema::Union{fields,count}=>{self.pending=Some(SchemaFrame{fields,count,index:0,root:Some(root),role:1,before:self.matched,best:NativeFieldMatch::Missing});self.matched=NativeFieldMatch::Missing;},NativeRecordSchema::Skip=>{}}}}
  else{self.done=true;}
  own=receipt(fixed(0));let step=if self.done{RetainedCloneStep::Complete(own)}else{RetainedCloneStep::Progress(own)};own=Default::default();Ok(step)
 })();let result=result.map_err(|error|{let p=error.retained_progress().checked_add(own).expect("one bounded schema probe fits its original grant");error.with_retained_progress(p)});RetainedWorkOutcome{result,work}}
 /// 🧮️ Several real schema probes spend the same remaining physical grant and publish one independent-work outcome.
 pub fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{
  if self.done{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}
  let mut progress=RetainedCloneProgress::default();let mut work=0;let mut left=g;let mut actions=0;
  let result=(||{while left.maximum_items!=0&&actions<g.maximum_items{actions+=1;
   let d=self.demands(input,body).map_err(|e|{let p=progress.checked_add(e.retained_progress()).expect("schema quote refusal retains prior funded progress");e.with_retained_progress(p)})?;
   if !retained_clone_grant_admits(left,d){break}
   if control.owned_bytes().checked_add(progress.retained_capacity_bytes).and_then(|n|n.checked_add(d.capacity_bytes)).is_none_or(|n|n>control.maximum_bytes()){return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native schema backing exceeds its original decoder ceiling").with_retained_progress(progress))}
   let turn=self.advance_one(input,control,body,left);work+=turn.work;let step=turn.result.map_err(|e|{let p=progress.checked_add(e.retained_progress()).expect("schema failure retains every prior funded probe");e.with_retained_progress(p)})?;let p=step.progress();progress=progress.checked_add(p).expect("schema probes fit their same admitted physical grant");if self.done||p==RetainedCloneProgress::default(){break}
   left.maximum_items=left.maximum_items.checked_sub(p.copied_items).expect("schema item remains in original grant");left.maximum_copy_bytes=left.maximum_copy_bytes.checked_sub(p.copied_bytes).expect("schema copy remains in original grant");left.maximum_capacity_bytes=left.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).expect("schema allocation remains in original grant");left.maximum_release_bytes=left.maximum_release_bytes.checked_sub(p.released_bytes).expect("schema release remains in original grant");
  }Ok(if self.done{RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)})})();
  if work==0&&progress==RetainedCloneProgress::default(){return RetainedWorkOutcome{result:result.map_err(Into::into),work}}
  control.receive_retained_work(g,RetainedWorkOutcome{result,work})
 }

 pub fn begin_close(&mut self){self.closing=true;}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if self.pending.is_some(){return Ok(fixed(0))}if !self.frames.is_empty(){return Ok(RetirementDemand{depth:page(self.frames.next_pop_depth_demand())?.max(1),..Default::default()})}if self.frames.allocated_bytes()!=0{return Ok(RetirementDemand{release_bytes:page(self.frames.next_release_allocation_bytes())?,depth:page(self.frames.next_release_depth_demand())?.max(1),..Default::default()})}if self.key.is_some()||self.leaf.is_some(){return Ok(fixed(0))}RetainedCloneBinding::close_demand(&self.binding,body)}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{let mut work=0;let result=(||{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.pending.take().is_some(){work=1;return Ok(RetainedCloneStep::Progress(receipt(fixed(0))))}if !self.frames.is_empty(){self.frames.pop();work=1;return Ok(RetainedCloneStep::Progress(receipt(fixed(0))))}if self.frames.allocated_bytes()!=0{let p=page(self.frames.release_empty_page(g.maximum_release_bytes))?;work=p.work;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:usize::from(p.progressed),copied_bytes:p.placed_bytes,retained_capacity_bytes:p.allocated_bytes,released_bytes:p.released_allocation_bytes}))}if self.key.is_some()||self.leaf.is_some(){self.key=None;self.leaf=None;work=1;return Ok(RetainedCloneStep::Progress(receipt(fixed(0))))}let turn=RetainedCloneBinding::close_one(&mut self.binding,g);work=turn.work;turn.result})();RetainedWorkOutcome{result,work}}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.frames.terminal_is_empty()&&self.pending.is_none()&&self.key.is_none()&&self.leaf.is_none()}
}
impl<I:NativeValueSource+?Sized>Drop for NativeRecordMatcher<I>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"native schema matcher requires funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.frames);}}}}
